SELECT CASE WHEN s.rating >= 4.6 THEN 'high' WHEN s.rating >= 2.2 THEN 'mid' ELSE 'low' END rating_bucket, s.country, SUM(CASE WHEN p.category = 'Fashion' THEN p.stock_qty ELSE 0 END) fashion_stock_qty, SORT_ARRAY(COLLECT_SET(p.category)) category_list FROM products p LEFT OUTER JOIN suppliers s ON s.id = p.supplier_id WHERE s.supplier_name LIKE 'S%' GROUP BY CASE WHEN s.rating >= 4.6 THEN 'high' WHEN s.rating >= 2.2 THEN 'mid' ELSE 'low' END, s.country ORDER BY country, 3
